CREATE DATABASE IF NOT EXISTS notes_portal CHARACTER SET utf8mb4;
USE notes_portal;
CREATE TABLE students (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admins (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL);
CREATE TABLE subjects (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE notes (id INT AUTO_INCREMENT PRIMARY KEY, subject_id INT NOT NULL, student_id INT NOT NULL, title VARCHAR(150) NOT NULL, filename VARCHAR(80) NOT NULL, original_name VARCHAR(200) NOT NULL, downloads INT DEFAULT 0, uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE, FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE);
INSERT INTO subjects(name) VALUES ('Mathematics'),('Physics'),('Computer Science'),('English'),('Chemistry');
